"use client"
import Image from 'next/image'
import { motion } from 'framer-motion'
import { useState } from 'react'
import type { Work } from '../content/works'

function Thumb({ item, onOpen }: { item: Work; onOpen: (w: Work) => void }) {
  return (
    <motion.div whileHover={{ scale: 1.02 }} className="group">
      <div
        onClick={() => onOpen(item)}
        className="polaroid cursor-pointer overflow-hidden rounded-sm relative"
      >
        <div className="washi" aria-hidden="true"></div>
        <div className="image-wrap relative w-full h-56 md:h-72">
          <Image src={item.image} alt={item.title} fill sizes="(max-width: 768px) 100vw, 33vw" className="object-cover" />
        </div>
        <div className="mt-2 text-sm font-medium px-2">{item.title}</div>
      </div>
    </motion.div>
  )
}

export default function Gallery({ items }: { items: Work[] }) {
  const [open, setOpen] = useState<Work | null>(null)

  return (
    <section id="gallery">
      <div className="grid grid-cols-2 md:grid-cols-3 gap-5">
        {items.map((item, index) => (
          <motion.div
            key={item.image}
            whileHover={{ y: -8, rotate: index % 2 === 0 ? -1.5 : 1.5, scale: 1.02 }}
            className="group"
          >
            <button
              type="button"
              onClick={() => setOpen(item)}
              className="polaroid relative block w-full overflow-hidden rounded-xl text-left"
            >
              <div className="washi" aria-hidden="true" />
              <div className="image-wrap relative h-64 w-full">
                <Image src={item.image} alt={item.title} fill sizes="(max-width: 768px) 100vw, 33vw" className="object-cover" />
              </div>
              <div className="bg-white px-3 py-3">
                <p className="text-sm font-semibold">{item.title}</p>
                <p className="text-xs text-sf-muted mt-1">{item.category} · {item.date}</p>
              </div>
            </button>
          </motion.div>
        ))}
      </div>

      {open && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 px-4 py-6">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="w-full max-w-4xl rounded-3xl bg-white shadow-2xl overflow-hidden"
          >
            <div className="relative h-[60vh] w-full">
              <Image src={open.image} alt={open.title} fill className="object-contain bg-black/5" />
            </div>
            <div className="p-6">
              <div className="flex items-start justify-between gap-4">
                <div>
                  <h3 className="text-2xl font-semibold">{open.title}</h3>
                  <p className="mt-2 text-sm text-sf-muted">{open.category} · {open.date}</p>
                </div>
                <button
                  type="button"
                  onClick={() => setOpen(null)}
                  className="rounded-full border border-sf-accent px-4 py-2 text-sm text-sf-accent"
                >
                  Tutup
                </button>
              </div>
              <p className="mt-4 text-sm text-sf-muted">{open.description || 'Detail karya ini ditampilkan dengan ukuran penuh.'}</p>
            </div>
          </motion.div>
        </div>
      )}
    </section>
  )
}
